/**
 * GET /media/menu/<file> — serve a menu photo from the photo store.
 * File names are generated by the server, so only that exact pattern is
 * accepted (no paths, no "..").
 */
import { readFile } from "node:fs/promises";
import { storageDir } from "@/server/menu";

const NAME = /^[\w.-]+\.(jpe?g|png|webp)$/i;
const TYPES: Record<string, string> = { jpg: "image/jpeg", jpeg: "image/jpeg", png: "image/png", webp: "image/webp" };

export async function GET(_req: Request, ctx: { params: Promise<{ file: string }> }) {
  const { file } = await ctx.params;
  if (!NAME.test(file) || file.includes("..")) return new Response("Not found", { status: 404 });
  try {
    const data = await readFile(storageDir("menu", file));
    const ext = file.split(".").pop()!.toLowerCase();
    return new Response(new Uint8Array(data), {
      headers: {
        "Content-Type": TYPES[ext] ?? "application/octet-stream",
        // Photo files are never overwritten (new uploads get new names).
        "Cache-Control": "public, max-age=31536000, immutable",
        "X-Content-Type-Options": "nosniff",
      },
    });
  } catch {
    return new Response("Not found", { status: 404 });
  }
}
